<script>
    import cloudsUrl from '@/../assets/clouds.png';
    import logoUrl from '@/../assets/logo.png';
    import testimonialUrl from '@/../assets/testimonialPicture.png';
    import phoneMockupUrl from '@/../assets/phoneMockup.png';
    import webMockupUrl from '@/../assets/webMockup.png';
    import chronicUrl from '@/../assets/chronicPicture.jpg';
    import img1profileUrl from '@/../assets/1profile.png';
    import img2menuUrl from '@/../assets/2menu.png';
    import img3coursesUrl from '@/../assets/3courses.png';
    import img4cookUrl from '@/../assets/4cook.png';
    
    import solutionImg1 from '@/../assets/1.png';
    import solutionImg2 from '@/../assets/2.png';
    import solutionImg3 from '@/../assets/3.png';
    import solutionImg4 from '@/../assets/4.png';
    import solutionImg5 from '@/../assets/5.png';
    import solutionImg6 from '@/../assets/6.png';
    import dashboardUrl from '@/../assets/dashboard.png';

    import { ref } from 'vue';

    export default {
        name: 'WelcomePage',
        setup() {
            const mobileMenuOpen = ref(false);
            const showScrollTop = ref(false);

            const scrollToTop = () => {
                window.scrollTo({ top: 0, behavior: 'smooth' });
            };

            window.addEventListener('scroll', () => {
                showScrollTop.value = window.scrollY > 400;
            }, { passive: true });
            const activePlatform = ref('web');
            const proplan = ref('monthly');

            const scrollToConstraints = () => {
                const target = document.getElementById('solution');
                if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            };

            const scrollToSteps = () => {
                const target = document.getElementById('steps-section');
                if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            };

            const scrollToPricing = () => {
                const target = document.getElementById('pricing');
                if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            };

            const handleNavScroll = () => {
                const header = document.querySelector('.welcome__nav');
                if (!header) return;
                if (window.scrollY > 40) {
                    header.classList.add('welcome__nav--scrolled');
                } else {
                    header.classList.remove('welcome__nav--scrolled');
                }
            };
            window.addEventListener('scroll', handleNavScroll, { passive: true });

            const initScrollReveal = () => {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('scroll-reveal--visible');
                            observer.unobserve(entry.target);
                        }
                    });
                }, { threshold: 0.06, rootMargin: "0px 0px -60px 0px" });
                document.querySelectorAll('.scroll-reveal').forEach(el => observer.observe(el));
            };

            const initPerspectiveScroll = () => {
                const card = document.querySelector('.hero__card');
                if (!card) return;
                const updatePerspective = () => {
                    const rect = card.getBoundingClientRect();
                    const windowH = window.innerHeight;
                    // Flat when card center reaches screen center
                    const cardCenter = rect.top + rect.height / 2;
                    const screenCenter = windowH / 2;
                    const distFromCenter = cardCenter - screenCenter;
                    const maxDist = windowH;
                    const progress = Math.min(1, Math.max(0, 1 - (distFromCenter / maxDist)));
                    const rotateX = 32 * (1 - progress);
                    const scale = 0.82 + 0.18 * progress;
                    card.style.transform = `perspective(900px) rotateX(${rotateX}deg) scale(${scale})`;
                };
                window.addEventListener('scroll', updatePerspective, { passive: true });
                updatePerspective();
            };

            setTimeout(() => {
                initScrollReveal();
                initPerspectiveScroll();
            }, 100);

            return {
                mobileMenuOpen,
                cloudsUrl, logoUrl, testimonialUrl, phoneMockupUrl, chronicUrl,
                img1profileUrl, img2menuUrl, img3coursesUrl, img4cookUrl,
                solutionImg1, solutionImg2, solutionImg3,
                solutionImg4, solutionImg5, solutionImg6,
                dashboardUrl, scrollToConstraints, scrollToPricing, scrollToSteps,
                activePlatform, webMockupUrl, proplan, showScrollTop, scrollToTop,
            };
        },
    }
</script>

