        background: none;
        border: none;
        cursor: pointer;
        padding: 6px;
        flex-shrink: 0;
    }

    .hamburger span {
        display: block;
        width: 22px;
        height: 2px;
        background: #1A1615;
        border-radius: 2px;
        transition: transform 0.3s ease, opacity 0.3s ease;
    }

    .hamburger--open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger--open span:nth-child(2) { opacity: 0; }
    .hamburger--open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* ===== BRAND ===== */
    .brand {
        display: flex;
        align-items: center;
        gap: 10px;
        font-weight: 600;
        letter-spacing: -0.02em;
        flex-shrink: 0;
    }

    .brand__mark { width: 38px; height: 38px; object-fit: contain; display: block; }
    .brand__name { font-size: 20px; text-transform: lowercase; }

    /* ===== NAV LINKS ===== */
    .navlinks {
        display: flex;
        gap: 24px;
        font-weight: 500;
        font-size: 0.95rem;
    }

    .navlinks__item {
        color: #1A1615;
        text-decoration: none;
        opacity: 1;
        font-size: 16px;
        font-weight: 400;
        font-family: "Open Runde", "Montserrat", "Segoe UI", sans-serif;
        transition: opacity 0.2s ease;
        background: transparent;
        border: none;
        cursor: pointer;
        padding: 0;
    }

    .navlinks__item:hover { opacity: 0.5; }

    .nav-actions {
        display: flex;
        gap: 16px;
        align-items: center;
        flex-shrink: 0;
    }

    .nav-actions__link {
        background: transparent;
        border: none;
        color: #1A1615;
        font-size: 16px;
        font-weight: 400;
        font-family: "Open Runde", "Montserrat", "Segoe UI", sans-serif;
        cursor: pointer;
        padding: 8px 4px;
        opacity: 1;
        transition: opacity 0.2s ease;
    }

    .nav-actions__link:hover { opacity: 0.5; }

    /* ===== BUTTONS ===== */
    .btn {
        border: none;
        border-radius: var(--welcome-radius);
        padding: 12px 26px;
        font-size: 0.95rem;
        font-weight: 600;
        cursor: pointer;
        transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
        text-decoration: none;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-family: inherit;
    }

    .btn--ghost {
        background: rgba(255, 255, 255, 0.7);
        color: var(--welcome-ink);
        box-shadow: inset 0 0 0 1px rgba(17, 17, 17, 0.12);
    }

    .btn--solid { background: var(--welcome-accent); color: #ffffff; }
    .btn--solid:hover { transform: translateY(-2px) !important; opacity: 0.85 !important; }
    .btn--ghost:hover { transform: translateY(-2px) !important; opacity: 0.85 !important; }
    .btn:hover {
        transform: translateY(-2px) !important;
        opacity: 0.85 !important;
    }

    /* ===== HERO ===== */
    .welcome__hero {
        padding: 120px var(--welcome-inline-pad) clamp(48px, 8vw, 96px);
        background: linear-gradient(180deg, #9CC1E7 0%, #EDDFD0 100%);
        position: relative;
        z-index: 1;
        overflow: hidden;
        height: 1020px;
        box-sizing: border-box;
    }

    .welcome__hero::before {
        content: "";
        position: absolute;
        inset: 0;
        background-image: var(--clouds-image);
        background-repeat: repeat-x;
        background-position: center 120px;
        background-size: 1400px auto;
        opacity: 0.95;
        pointer-events: none;
        z-index: 0;
    }

    .welcome__hero::after {
        display: none;
    }

    .welcome__hero > * { position: relative; z-index: 1; }

    .hero {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 20px;
        width: 100%;
        max-width: 1240px;
        margin-inline: auto;
        padding-bottom: clamp(24px, 6vw, 64px);
    }

    .hero__content {
        text-align: center;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 18px;
    }

    .hero__title {
        font-size: clamp(2.2rem, 5.5vw, 68px);
        font-weight: 600;
        letter-spacing: -0.03em;
        margin: 0;
        margin-top: 48px;
        line-height: 1.15;
        text-align: center;
        width: fit-content;
    }

    .hero__title-line { display: block; white-space: nowrap; text-align: center; width: 100%; }

    .hero__subtitle {
        margin: 0;
        font-size: 20px;
        line-height: 1.7;
        color: #453F3D;
        max-width: 680px;
    }

    .hero__actions {
        display: flex;
        flex-wrap: wrap;
        gap: 16px;
        justify-content: center;
        margin-top: 10px;
    }

    .hero__visual {
        display: flex;
        justify-content: center;
        margin-top: clamp(28px, 6vw, 54px);
        width: 100%;
    }

    .hero__card {
        width: 900px;
        max-width: 94vw;
        margin-inline: auto;
        transform-origin: top center;
        will-change: transform;
    }

    .hero__image {
        width: 100%;
        height: auto;
        object-fit: contain;
        display: block;
        border-radius: 20px;
        box-shadow: 0 40px 80px rgba(20, 28, 40, 0.22);
    }

    /* ===== BODY (gradient wrapper) ===== */
    .welcome__body {
        background: linear-gradient(180deg, #ffffff 0%, #C3DBF3 100%);
        position: relative;
    }

    /* ===== CHRONIC ===== */
    .chronic {
        padding: clamp(64px, 10vw, 120px) var(--welcome-inline-pad);
    }

    .chronic__inner {
        max-width: 1150px;
        margin-inline: auto;
        display: grid;
        grid-template-columns: minmax(280px, 1fr) minmax(320px, 1fr);
        gap: clamp(28px, 5vw, 56px);
        align-items: center;
    }

    .chronic__media {
        border-radius: 28px;
        padding: 18px;
        background: linear-gradient(180deg, rgba(152, 190, 230, 0.6) 0%, rgba(244, 226, 205, 0.7) 100%);
        box-shadow: 0 24px 48px rgba(20, 30, 45, 0.18);
    }

    .chronic__image { width: 100%; height: 615px; display: block; border-radius: 20px; object-fit: cover; }

    .chronic__content { display: flex; flex-direction: column; gap: 16px; }

    .chronic__eyebrow { font-size: 15px; letter-spacing: 0em; line-height: 125%; text-transform: uppercase; font-weight: 600; color: #614A44; }

    .chronic__title { margin: 0; font-size: 52px; font-weight: 600; color: #1A1615; line-height: 120%; letter-spacing: -0.03em; }
    .chronic__text { margin: 0; font-size: 1rem; line-height: 1.65; color: #3a424c; }

    .chronic__cta {
        align-self: flex-start;
        margin-top: 10px;
        padding: 12px 22px;
        border-radius: 999px;
        border: none;
        background: #1A1615;
        color: #ffffff;
        font-weight: 600;
        cursor: pointer;
        font-family: inherit;
        transition: transform 0.2s ease, opacity 0.2s ease;
    }

    .chronic__cta:hover { transform: translateY(-2px) !important; opacity: 0.85 !important; }

    /* ===== SOLUTION ===== */
    .solution { padding: clamp(72px, 12vw, 140px) var(--welcome-inline-pad); }

    .solution__inner {
        max-width: 1120px;
        margin-inline: auto;
        text-align: center;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 18px;
    }

    .solution__title-mobile { display: none; }
    .solution__title-desktop { display: inline; }

    .solution__eyebrow { font-size: 15px; letter-spacing: 0em; line-height: 125%; text-transform: uppercase; font-weight: 600; color: #614A44; }

    .solution__title { margin: 0 0 40px; font-size: 52px; font-weight: 600; color: #1A1615; line-height: 120%; letter-spacing: -0.03em; }

    .solution-card {
        margin-top: 18px;
        background: rgba(245, 236, 227, 0.92);
        border-radius: 28px;
        padding: 28px;
        width: 100%;
        height: auto;
        text-align: left;
        box-shadow: none;
        box-sizing: border-box;
    }

    .solution-card__title { margin: 0 0 52px; font-size: 28px; font-weight: 600; color: #1A1615; line-height: 140%; letter-spacing: -0.03em; }

    .solution-carousel {
        width: 100%;
        overflow: hidden;
        margin-bottom: 48px;
        mask-image: linear-gradient(90deg, transparent, black 8%, black 92%, transparent);
        -webkit-mask-image: linear-gradient(90deg, transparent, black 8%, black 92%, transparent);
    }

    .solution-carousel__track {
        display: flex;
        gap: 32px;
        animation: carouselScroll 30s linear infinite;
        width: max-content;
    }

    .solution-carousel__item {
        flex-shrink: 0;
        width: 250px;
        height: 350px;
        border-radius: 10px;
        overflow: hidden;
    }

    .solution-carousel__item img { width: 100%; height: 100%; object-fit: cover; display: block; }

    @keyframes carouselScroll {
        0%   { transform: translateX(0); }
        100% { transform: translateX(calc(-50% - 7px)); }
    }

    .solution-carousel:hover .solution-carousel__track { animation-play-state: paused; }

    .solution-card__text { margin: 0; font-size: 18px; line-height: 1.6; color: #453F3D; }

    .solution__bottom {
        width: 100%;
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
        gap: 18px;
        margin-top: 18px;
    }

    .solution-mini {
        background: rgba(245, 236, 227, 0.92);
        border-radius: 20px;
        padding: 18px 20px;
        text-align: left;
        box-shadow: none;
        height: auto;
        box-sizing: border-box;
    }

    .solution-mini h3 { margin: 0 0 32px; font-size: 28px; font-weight: 600; color: #1A1615; line-height: 140%; letter-spacing: -0.03em; }
    .solution-mini p { margin: 0; color: #453F3D; font-size: 18px; line-height: 1.6; }

    /* ===== STEPS ===== */
    .steps { padding: clamp(72px, 12vw, 140px) var(--welcome-inline-pad); }

    .steps__inner {
        max-width: 1020px;
        margin-inline: auto;
        text-align: center;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 18px;
    }

    .steps__eyebrow { font-size: 15px; letter-spacing: 0em; line-height: 125%; text-transform: uppercase; font-weight: 600; color: #614A44; }

    .steps__title { margin: 0 0 40px; font-size: 52px; font-weight: 600; color: #1A1615; line-height: 120%; letter-spacing: -0.03em; }

    .steps__grid {
        margin-top: 22px;
        display: grid;
        grid-template-columns: repeat(2, 540px);
        gap: 20px;
        width: 100%;
        justify-content: center;
    }

    .steps-card {
        background: rgba(255, 255, 255, 0.85);
        border-radius: 26px;
        padding: 20px 20px 16px;
        box-shadow: none;
        display: flex;
        flex-direction: column;
        gap: 10px;
        text-align: left;
        height: auto;
        min-height: 400px;
        width: 540px;
        max-width: 100%;
        box-sizing: border-box;
        flex-shrink: 0;
    }

    .steps-card__image { width: 100%; height: 240px; object-fit: cover; border-radius: 18px; display: block; margin-bottom: 24px; }
    .steps-card__title { margin: 0; font-size: 28px; font-weight: 600; color: #1A1615; line-height: 140%; letter-spacing: -0.03em; }
    .steps-card__text { margin: 0 0 8px; color: #453F3D; font-size: 18px; line-height: 1.6; font-weight: 400; }

    /* ===== PLATFORMS ===== */
    .platforms { padding: clamp(72px, 12vw, 140px) var(--welcome-inline-pad); }

    .platforms__inner {
        max-width: 1020px;
        margin-inline: auto;
        text-align: center;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 18px;
    }

    .platforms__eyebrow { font-size: 15px; letter-spacing: 0em; line-height: 125%; text-transform: uppercase; font-weight: 600; color: #614A44; }

    .platforms__title { margin: 0 0 40px; font-size: 52px; font-weight: 600; color: #1A1615; line-height: 120%; letter-spacing: -0.03em; }

    .platforms__card {
        margin-top: 26px;
        width: min(980px, 92vw);
        border-radius: 28px;
        overflow: hidden;
        box-shadow: 0 30px 60px rgba(20, 28, 40, 0.18);
        position: relative;
    }

    .platforms__image { width: 100%; height: auto; display: block; object-fit: cover; }

    .platforms__switch {
        position: absolute;
        left: 50%;
        bottom: 16px;
        transform: translateX(-50%);
        display: inline-flex;
        gap: 6px;
        background: rgba(0, 0, 0, 0.4);
        border-radius: 999px;
        padding: 5px;
        backdrop-filter: blur(6px);
        white-space: nowrap;
        z-index: 2;
    }

    .platforms__pill { color: #fff; font-size: clamp(0.75rem, 1.5vw, 0.9rem); font-weight: 600; padding: 5px clamp(10px, 2vw, 16px); border-radius: 999px; background: rgba(255,255,255,0.2); }
    .platforms__pill--active { background: #ffffff; color: #1A1615; }

    /* ===== TESTIMONIAL ===== */
    .testimonial { padding: clamp(80px, 12vw, 140px) var(--welcome-inline-pad) clamp(100px, 14vw, 160px); }

    .testimonial__inner {
        max-width: 860px;
        margin-inline: auto;
        text-align: center;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 18px;
    }

    .testimonial__title { margin: 0 0 40px; font-size: 52px; font-weight: 600; color: #1A1615; line-height: 120%; letter-spacing: -0.03em; }

    .testimonial__quote { margin: 0; font-size: 20px; line-height: 1.75; color: #453F3D; max-width: 920px; }

    .testimonial__avatar {
        width: 60px; height: 60px;
        border-radius: 50%;
        background-image: var(--testimonial-avatar);
        background-size: cover;
        background-position: center;
        box-shadow: 0 10px 20px rgba(20, 30, 45, 0.16);
        border: 3px solid #ffffff;
    }

    .testimonial__person { margin-top: 6px; display: flex; flex-direction: column; align-items: center; gap: 12px; }
    .testimonial__identity { display: flex; flex-direction: column; gap: 2px; align-items: center; }
    .testimonial__name { margin: 0; font-size: 14px; font-weight: 600; color: #757170; }
    .testimonial__role { margin: 0; font-size: 16px; color: #1A1615; }

    /* ===== PRICING ===== */
    .pricing { padding: clamp(72px, 12vw, 140px) var(--welcome-inline-pad); }

    .pricing__inner {
        max-width: 940px;
        margin-inline: auto;
        text-align: center;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 24px;
    }

    .pricing__badge { font-size: 15px; letter-spacing: 0em; line-height: 125%; text-transform: uppercase; font-weight: 600; color: #614A44; }
    .pricing__title { margin: 0; font-size: 52px; font-weight: 600; color: #1A1615; line-height: 120%; letter-spacing: -0.03em; }

    .pricing__grid {
        margin-top: 20px;
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 24px;
        width: 100%;
        align-items: end;
        justify-items: center;
    }

    .pricing-card {
        background: rgba(255, 255, 255, 0.85);
        border-radius: 26px;
        padding: 28px 26px 30px;
        box-shadow: 0 24px 50px rgba(20, 30, 45, 0.14);
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        gap: 18px;
        text-align: left;
        max-width: 360px;
        width: 100%;
    }

    .pricing-card--highlight {
        background: linear-gradient(180deg, rgba(129, 178, 228, 0.25) 0%, rgba(255, 255, 255, 0.95) 55%);
        border: 3px solid rgba(125, 170, 220, 0.9);
        box-shadow: 0 28px 60px rgba(20, 40, 60, 0.2);
    }

    .pricing-card__toggle {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 6px;
        background: rgba(255, 255, 255, 0.85);
        border-radius: 999px;
        padding: 6px;
        width: 100%;
        max-width: 250px;
        box-shadow: inset 0 0 0 1px rgba(18, 20, 24, 0.08);
    }

    .pricing-card__tab { text-align: center; padding: 6px 12px; border-radius: 999px; font-weight: 600; font-size: 0.9rem; color: #4b5563; }
    .pricing-card__tab--active { background: #ffffff; color: #1A1615; box-shadow: 0 10px 18px rgba(20, 30, 45, 0.15); }

    .pricing-card__head { display: flex; flex-direction: column; gap: 10px; }
    .pricing-card__plan { display: flex; align-items: center; gap: 10px; font-weight: 600; font-size: 0.98rem; }

    .pricing-card__pill {
        background: #e7ffe4;
        color: #2f7d33;
        font-size: 0.78rem;
        padding: 4px 10px;
        border-radius: 999px;
        font-weight: 600;
        border: 1px solid rgba(47, 125, 51, 0.2);
    }

    .pricing-card__plan-name { font-weight: 600; font-size: 1rem; margin: 0; }
    .pricing-card__price { font-size: clamp(1.8rem, 3vw, 2.2rem); font-weight: 700; margin: 0; }
    .pricing-card__subtitle { margin: 0; color: #4b5563; font-size: 0.98rem; line-height: 1.5; }

    .pricing-card__list { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 12px; color: #2c333d; font-size: 0.97rem; }
    .pricing-card__list li { position: relative; padding-left: 26px; }
    .pricing-card__list li::before { content: "✓"; position: absolute; left: 0; top: 0; font-weight: 700; }

    .pricing-card__cta {
        margin-top: auto;
        width: 100%;
        padding: 12px 18px;
        border-radius: 999px;
        border: none;
        font-weight: 600;
        font-size: 0.95rem;
        background: rgba(30, 30, 30, 0.08);
        color: #1A1615;
        cursor: pointer;
        font-family: inherit;
        transition: transform 0.2s ease, opacity 0.2s ease;
    }

    .pricing-card__cta:hover {
        transform: translateY(-2px);
        opacity: 0.8;
    }

    .pricing-card__cta--dark { background: #1A1615; color: #ffffff; }
    .pricing-card__cta--dark:hover { transform: translateY(-2px); opacity: 0.85; }

    /* ===== CTA FINAL ===== */
    .cta-final {
        padding: clamp(36px, 6vw, 56px) 0;
        background: transparent;
        position: relative;
        overflow: hidden;
    }

    .cta-final::before {
        content: "";
        position: absolute;
        inset: 0;
        background-image: var(--clouds-image);
        background-repeat: repeat-x;
        background-position: center;
        background-size: 1400px auto;
        opacity: 0.95;
        pointer-events: none;
    }

    .cta-final__inner {
        max-width: 980px;
        margin-inline: auto;
        text-align: center;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
        padding: clamp(20px, 3vw, 32px) 20px;
        position: relative;
        z-index: 1;
    }

    .cta-final__title { margin: 0; font-size: 52px; font-weight: 600; color: #1A1615; line-height: 120%; letter-spacing: -0.03em; }
    .cta-final__subtitle { margin: 0; color: var(--welcome-muted); font-size: 1rem; }

    .cta-final__button {
        margin-top: 8px;
        padding: 12px 26px;
        border-radius: 999px;
        border: none;
        background: #1A1615;
        color: #ffffff;
        font-weight: 600;
        cursor: pointer;
        font-family: inherit;
        transition: transform 0.2s ease, opacity 0.2s ease;
    }

    .cta-final__button:hover { transform: translateY(-2px); opacity: 0.85; }

    /* ===== SCROLL TO TOP ===== */
    .scroll-top {
        position: fixed;
        bottom: 32px;
        right: 32px;
        width: 48px;
        height: 48px;
        border-radius: 999px;
        background: #1A1615;
        color: #ffffff;
        border: none;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        box-shadow: 0 4px 16px rgba(20, 28, 40, 0.2);
        opacity: 0;
        transform: translateY(16px);
        transition: opacity 0.3s ease, transform 0.3s ease;
        z-index: 999;
        pointer-events: none;
    }

    .scroll-top--visible {
        opacity: 1;
        transform: translateY(0);
        pointer-events: auto;
    }

    .scroll-top:hover { opacity: 0.8; transform: translateY(-2px); }

    .scroll-top svg { width: 20px; height: 20px; }

    /* ===== ANIMATIONS ===== */
    .anim-fade-up {
        opacity: 0;
        transform: translateY(36px);
        animation: welcomeFadeUp 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
        animation-delay: var(--delay, 0ms);
    }

    .anim-fade-down {
        opacity: 0;
        transform: translateY(-20px);
        animation: welcomeFadeDown 0.7s cubic-bezier(0.22, 1, 0.36, 1) forwards;
    }

    @keyframes welcomeFadeUp { to { opacity: 1; transform: translateY(0); } }
    @keyframes welcomeFadeDown { to { opacity: 1; transform: translateY(0); } }

    .scroll-reveal {
        opacity: 0;
        transform: translateY(40px);
        transition: opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1),
                    transform 0.75s cubic-bezier(0.22, 1, 0.36, 1);
    }

    .scroll-reveal--visible { opacity: 1; transform: translateY(0); }

    /* ===== RESPONSIVE ===== */

    /* PC portable 1400px */
    @media (max-width: 1440px) {
        .welcome__hero { height: 860px; padding: 80px var(--welcome-inline-pad) 0; }
        .chronic { padding: 80px var(--welcome-inline-pad); padding-top: 180px; }
        .chronic__title { font-size: 40px; }
        .chronic__inner { max-width: 960px; }
        .chronic__image { height: 480px; }

        .solution { padding: 80px var(--welcome-inline-pad); }
        .solution__title { font-size: 40px; margin-bottom: 24px; }
        .solution__inner { max-width: 860px; }
        .solution-carousel__item { width: 180px; height: 280px; }

        .steps { padding: 80px var(--welcome-inline-pad); }
        .steps__title { font-size: 40px; margin-bottom: 24px; }
        .steps__inner { max-width: 860px; }
        .steps__grid { grid-template-columns: repeat(2, 420px); gap: 16px; }
        .steps-card { width: 420px; height: 360px; }
        .steps-card__image { height: 160px; }
        .steps-card__title { font-size: 22px; }
        .steps-card__text { font-size: 15px; }

